-- 0032: Repair extra escaping in the existing English whack-a-mole project JSON.
UPDATE projects SET en='{"id":"whack-a-mole","cover":"/images/whack-a-mole/machines-group.jpg","category":"高職選手作品","title":"Wireless Whack-a-Mole (Special Ed Aid)","period":"2021 – 2022","description":"Built a wireless whack-a-mole teaching aid for the Nangang VHS special education department. ESP32/ESP-NOW connects one master to four game units. I fixed component damage caused by relay-coil back-EMF, then addressed 7805 overheating. The department issued a letter of appreciation.","tags":["ESP32","ESP-NOW","Circuit Design","3D Printing","Arduino"],"detail":{"purpose":"The special education department needed an interactive teaching aid that was easy to operate and maintain. We chose a whack-a-mole format with one master controlling four wireless units.","concept":"ESP32 boards send game states over ESP-NOW; buttons and relays control each unit. I added a 1N4001 flyback diode across relay coils to handle back-EMF, then checked the load and heat dissipation around the 7805 linear regulator.","outcome":"Five units were assembled and delivered to the department, which issued a letter of appreciation. I worked through wireless communication, relay protection, and linear-regulator heating.","images":[{"src":"/images/whack-a-mole/machines-group.jpg","caption":"All 5 units (1 master + 4 slaves) lit up — yellow, red, blue LED buttons"},{"src":"/images/whack-a-mole/machine-single.jpg","caption":"Single unit: aluminum tube enclosure + wood top cover + large LED button"},{"src":"/images/whack-a-mole/circuit-schematic.jpg","caption":"Circuit design sketch: 11.1V → 7805 → ESP32 → 9013 transistor → relay → LED"},{"src":"/images/whack-a-mole/circuit-board.jpg","caption":"Circuit board: ESP32 + relay wiring with 1N4001 flyback diode protection"},{"src":"/images/whack-a-mole/esp32-buttons.jpg","caption":"Close-up of 5-unit LED buttons: yellow/red/blue large buttons, student demonstration"},{"src":"/images/whack-a-mole/esp32-circuit.jpg","caption":"ESP32 + relay board: blue relay modules and 18650 battery wiring"},{"src":"/images/whack-a-mole/esp32-internal.jpg","caption":"Internal assembly: ESP32 board mounted in 3D-printed frame, magnetic bottom cover"}],"tech":[{"group":"Wireless Communication","items":[{"name":"Multi-Unit P2P Coordination","desc":"Designed 1-master 4-slave broadcast state machine; mastered ESP-NOW device pairing, broadcast reset, and auto-reconnect in a router-free environment; implemented master/slave logic in Arduino C++"}]},{"group":"Circuit Design","items":[{"name":"Transistor Current Amplification","desc":"Calculated 9013 NPN base current-limiting resistor for saturation conduction, solving ESP32 GPIO current insufficient to directly drive relay"},{"name":"High-Voltage Load Isolation","desc":"Relay fully isolates 3.3V control from 11.1V load; understanding contact capacity limits and switching frequency effects on contact lifespan"},{"name":"Back-EMF Protection","desc":"1N4001 flyback diode across relay coil absorbs inductive back-EMF on turn-off; necessity understood only after diagnosing actual ESP32 failure in the field"},{"name":"Power Regulation & Decoupling","desc":"7805 linear regulator with ceramic decoupling capacitors to eliminate power glitches from motor/relay switching; diagnosed 7805 overheating and understood linear regulator power dissipation limits"}]},{"group":"Maintenance-Oriented Mechanical Design","items":[{"name":"Quick-Swap Structure","desc":"\"Keep it simple\" principle: top cover changed from 3D print to wood to shorten replacement time; magnetic bottom cover for tool-free battery access, designed specifically for on-site special education maintenance needs"}]}],"github":""}}', updated_at=datetime('now') WHERE id='whack-a-mole' AND json_valid(en)=0;
